20	    * { box-sizing: border-box; }
21	    body { margin: 0; min-height: 100vh; background: var(--wash); color: var(--ink); }
22	    button, input, textarea { font: inherit; }
23	    button { cursor: pointer; }
24	    .shell { min-height: 100vh; }
25	    header {
