27	      border-bottom: 1px solid var(--line); background: rgba(255,254,249,.94);
28	    }
29	    .brand { display: flex; align-items: center; gap: 10px; font-weight: 780; font-size: 20px; letter-spacing: -.4px; }
30	    .brand-mark { width: 28px; height: 34px; border-radius: 4px 4px 10px 10px; background: var(--green); position: relative; }
31	    .brand-mark::after { content: ""; position: absolute; left: 8px; bottom: 6px; width: 12px; height: 12px; border: 2px solid var(--paper); border-radius: 50%; }
32	    .profile { width: 34px; height: 34px; border: 0; border-radius: 50%; background: #dce9e1; color: var(--green-dark); font-weight: 750; }
33	    main { width: min(1080px, 90vw); margin: 0 auto; padding: 46px 0 70px; }
34	    .topline { display: flex; justify-content: space-between; align-items: center; gap: 20px; }
35	    h1 { margin: 0; font-family: Georgia, serif; font-size: clamp(34px, 5vw, 50px); font-weight: 500; letter-spacing: -1.4px; }
36	    .primary { border: 0; border-radius: 10px; background: var(--green); color: white; padding: 12px 18px; font-weight: 700; box-shadow: 0 2px 0 var(--green-dark); }
37	    .primary:hover { background: var(--green-dark); }
38	    .primary:focus-visible, .secondary:focus-visible, input:focus-visible, textarea:focus-visible { outline: 3px solid rgba(230,163,76,.5); outline-offset: 2px; }
39	    .secondary { border: 1px solid var(--line); border-radius: 10px; background: var(--paper); color: var(--ink); padding: 11px 16px; font-weight: 650; }
40	    .empty { margin-top: 34px; min-height: 430px; border: 1px dashed #bdc8c0; border-radius: 18px; background: rgba(255,254,249,.65); display: grid; place-items: center; text-align: center; padding: 30px; }
41	    .empty-inner { max-width: 420px; }
42	    .empty-art { width: 92px; height: 92px; margin: 0 auto 24px; border-radius: 50%; background: #e2ebe3; display: grid; place-items: center; font-family: Georgia, serif; color: var(--green); font-size: 38px; }
43	    .empty h2 { margin: 0 0 10px; font-family: Georgia, serif; font-size: 28px; font-weight: 500; }
44	    .empty p { margin: 0 0 24px; color: var(--muted); line-height: 1.55; }
45	    dialog { width: min(560px, calc(100vw - 28px)); border: 0; border-radius: 18px; padding: 0; box-shadow: 0 24px 70px rgba(25,50,38,.23); background: var(--paper); }
46	    dialog::backdrop { background: rgba(19,31,24,.48); backdrop-filter: blur(2px); }
47	    .dialog-body { padding: 28px; }
48	    .dialog-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
49	    .dialog-head h2 { margin: 0; font-family: Georgia, serif; font-size: 28px; font-weight: 500; }
50	    .dialog-head p { margin: 7px 0 0; color: var(--muted); }
51	    .close { border: 0; background: transparent; font-size: 25px; line-height: 1; color: var(--muted); padding: 2px 4px; }
52	    label { display: block; margin: 24px 0 8px; font-weight: 720; font-size: 14px; }
