152	  <script>
153	    const dialog = document.querySelector('#addDialog');
154	    const urlStep = document.querySelector('#urlStep');
155	    const fetchStep = document.querySelector('#fetchStep');
156	    const reviewStep = document.querySelector('#reviewStep');
157	    const urlInput = document.querySelector('#url');
158	    const showStep = (step) => [urlStep, fetchStep, reviewStep].forEach(el => el.hidden = el !== step);
159	    document.querySelectorAll('.add-button').forEach(button => button.addEventListener('click', () => {
160	      showStep(urlStep); urlInput.value = ''; dialog.showModal(); setTimeout(() => urlInput.focus(), 0);
161	    }));
162	    document.querySelector('#continueButton').addEventListener('click', () => {
163	      if (!urlInput.reportValidity()) return;
164	      showStep(fetchStep);
165	      setTimeout(() => {
166	        document.querySelector('#previewUrl').textContent = urlInput.value;
167	        showStep(reviewStep);
168	      }, 700);
169	    });
170	    document.querySelector('#backButton').addEventListener('click', () => showStep(urlStep));
171	    document.querySelector('#saveButton').addEventListener('click', () => {
172	      dialog.close();
173	      document.querySelector('#emptyState').hidden = true;
174	      document.querySelector('#library').hidden = false;
175	    });
176	    document.querySelector('#resetButton').addEventListener('click', () => {
177	      document.querySelector('#library').hidden = true;
178	      document.querySelector('#emptyState').hidden = false;
179	    });
180	  </script>
